// Preenche pai/mãe em leads cujo formulário já foi aplicado antes de o app copiar esses campos.
function leadFormBackfill(){
  try{
    const leads=loadLeads(); let n=0;
    leads.forEach(l=>{
      const d=l.cadastroForm&&l.cadastroForm.dados; if(!d) return;
      if(d.mae&&!l.mae){ l.mae=d.mae; n++; }
      if(d.pai&&!l.pai){ l.pai=d.pai; n++; }
    });
    if(n) saveLeads(leads);
    return n;
  }catch(e){ return 0; }
}
