// Ficha somente leitura do paciente (com botão Editar para abrir o formulário)
function ecModo(m){
  const mo=document.getElementById('modal-conv'); if(!mo) return;
  const box=mo.querySelector('.modal'); if(!box) return;
  box.classList.toggle('ec-view',m==='ver');
  const t=document.getElementById('ec-titulo');
  if(t) t.textContent=m==='ver'?(document.getElementById('ec-paciente')?.value||'Paciente'):'Editar paciente';
  const b=box.querySelector('.modal-body.ec-form'); if(b) b.scrollTop=0;
}
function ecRenderFicha(p){
  const el=document.getElementById('ec-ficha-body'); if(!el) return;
  const R=(k,v)=>{const ok=v!==undefined&&v!==null&&String(v).trim()!=='';return '<div class="ec-row"><span class="ec-k">'+esc(k)+'</span><span class="ec-v'+(ok?'':' vazio')+'">'+(ok?esc(String(v)):'—')+'</span></div>';};
  const S=t=>'<div class="ec-sec">'+t+'</div>';
  let idade='';
  if(p.nascimento){ const n=new Date(p.nascimento+'T12:00:00'),h=new Date(); if(!isNaN(n)){ let a=h.getFullYear()-n.getFullYear(); if(h<new Date(h.getFullYear(),n.getMonth(),n.getDate())) a--; idade=' ('+a+' anos)'; } }
  const brl=v=>(v||v===0)&&Number(v)>0?Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'';
  const mod=p.modalidade||'mensal';
  let cob='';
  if(mod==='mensal'){ cob=R('Modalidade','Mensal fixo')+R('Valor mensal',brl(p.valorMensal||p.valor))+(p.valorProporcional?R('Proporcional 1º mês',brl(p.valorProporcional)):''); }
  else { cob=R('Modalidade',mod==='unica'?'Sessão única':'Por sessão')+R('Valor por sessão',brl(p.valor))+(mod==='avulso'?R('Dia da semana',p.diaSemana!=null&&p.diaSemana!==''?DIAS_SEMANA[p.diaSemana]:'')+R('Frequência',p.frequencia==='quinzenal'?'Quinzenal':'Semanal'):''); }
  el.innerHTML=
    S('Paciente')+R('Nome completo',p.paciente)+R('Data de nascimento',p.nascimento?preCadFmtData(p.nascimento)+idade:'')+R('CPF da criança / paciente',p.cpfPaciente)+R('Escola',p.escola)+R('Status',p.ativo===false?'⛔ Inativo':'✅ Ativo')+
    S('Responsáveis')+R('Responsável legal',p.responsavelLegal)+R('CPF do responsável',p.cpf)+R('Nome do pai',p.pai)+R('Nome da mãe',p.mae)+R('Contato de emergência',p.contatoEmergencia)+
    S('Contato')+R('Telefone',p.telefone)+R('Celular 2',p.telefone2)+R('E-mail',p.email)+R('Endereço com CEP',p.endereco)+
    S('Atendimento')+R('Serviço',p.servico)+R('Terapeuta',p.terapeuta)+R('Onde nos conheceu',p.origem)+R('Nota fiscal',p.notaFiscal==='sim'?'Precisa de NF todo mês':'Não precisa de NF')+
    S('Cobrança')+cob+
    S('Queixa')+R('Queixa',p.queixa)+
    S('Observação')+R('Observação',p.observacao);
}
